INSERT INTO course_schedules (course_id, day_of_week, period_code, period_name, classroom, start_time, end_time)
SELECT c.id, t.day_of_week, t.period_code, t.period_name, t.classroom, t.start_time, t.end_time
FROM tmp_course_schedules t
JOIN courses c
  ON c.haksu_code = t.haksu_code
 AND c.academic_year = 2026
 AND c.term = 'SECOND';

DROP TEMPORARY TABLE tmp_course_schedules;
